import{_ as a,o as e,c as d,a6 as r}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"跨境本地化：英文、日文、单位与准确文字","description":"","frontmatter":{"id":"localization","title":"跨境本地化：英文、日文、单位与准确文字","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","visual-copywriting","cross-border-knowledge"],"platform_rule_ids":[],"order":23.6,"content_kind":"操作教程"},"headers":[],"relativePath":"ecommerce/localization.md","filePath":"ecommerce/localization.md"}'),o={name:"ecommerce/localization.md"};function i(n,t,s,l,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="跨境本地化-实际改一次英文、日文和尺寸图" tabindex="-1">跨境本地化，实际改一次英文、日文和尺寸图 <a class="header-anchor" href="#跨境本地化-实际改一次英文、日文和尺寸图" aria-label="Permalink to &quot;跨境本地化，实际改一次英文、日文和尺寸图&quot;">​</a></h1><p>这节得到事实对应词表、英文和日文短文案、单位换算记录，以及两份可编辑排版稿。翻译调整表达和阅读顺序，商品参数与发货内容保持一致。沿用DN01虚构收纳盒数据演示，正式商品替换真实记录。</p><h2 id="_1-给词表保留事实来源" tabindex="-1">1. 给词表保留事实来源 <a class="header-anchor" href="#_1-给词表保留事实来源" aria-label="Permalink to &quot;1. 给词表保留事实来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文</th><th>英文练习</th><th>日文练习</th></tr></thead><tbody><tr><td>带盖桌面收纳盒</td><td>Lidded desk organizer</td><td>ふた付きデスク収納ボックス</td></tr><tr><td>可拆隔板</td><td>Removable divider</td><td>取り外し可能な仕切り</td></tr><tr><td>外尺寸</td><td>External dimensions</td><td>外寸</td></tr><tr><td>场景文具不随商品发货</td><td>Stationery is not included</td><td>文房具は付属しません</td></tr></tbody></table><p>每个词旁边记录规格表或照片依据。日文例句是编辑草稿，正式面向客户的版本仍需熟悉当地表达的人复核；语言流畅不能证明功能真实。</p><h2 id="_2-先翻事实-再缩短标题" tabindex="-1">2. 先翻事实，再缩短标题 <a class="header-anchor" href="#_2-先翻事实-再缩短标题" aria-label="Permalink to &quot;2. 先翻事实，再缩短标题&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请把下面的收纳盒事实与短文案分别整理成英文和日文。产品为带盖桌面收纳盒，白色ABS，外尺寸220×150×120mm，一个可拆隔板，发货含盒体1、盖子1、隔板1，文具不包含。这些是练习设定，正式发布会替换。</span></span>
<span class="line"><span>输出三列对照表，事实字段保留数值、数量和单位；营销标题可以简短自然，但不得添加防水、耐温、食品接触、认证、环保或容量声明。给每条短标题一个更短版本，供手机排版。尺寸写L×W×H，外尺寸与内尺寸分开。</span></span>
<span class="line"><span>指出可能需要当地语言复核的词，不把翻译草稿称为已通过平台审核。</span></span></code></pre></div><p>先看事实列有没有被改，再挑短标题。中文两字变成英文长词时，扩文本框或拆行；不能删掉关键限制来适应版面。英语 <code>Removable divider</code> 比加上未经证实的 <code>Flexible large-capacity storage system</code> 更准确。</p><h2 id="_3-单位换算-算完再排版" tabindex="-1">3. 单位换算，算完再排版 <a class="header-anchor" href="#_3-单位换算-算完再排版" aria-label="Permalink to &quot;3. 单位换算，算完再排版&quot;">​</a></h2><p>英寸与毫米按1in＝25.4mm换算，DN01示例得到如下值。<a href="https://www.nist.gov/pml/owm/si-units-length" target="_blank" rel="noreferrer">NIST长度单位</a>。</p><table tabindex="0"><thead><tr><th>方向</th><th>原值</th><th>英寸，保留两位小数</th></tr></thead><tbody><tr><td>L</td><td>220 mm</td><td>8.66 in</td></tr><tr><td>W</td><td>150 mm</td><td>5.91 in</td></tr><tr><td>H</td><td>120 mm</td><td>4.72 in</td></tr></tbody></table><p>排版文字可以是 <code>External dimensions: 8.66 × 5.91 × 4.72 in / 220 × 150 × 120 mm (L × W × H)</code>。毫米仍保留原测量值，英寸是转换结果，小数位不代表实物精度提高。没有容积记录就不从外尺寸乘积计算容量。</p><h2 id="_4-在源文件里替换语言" tabindex="-1">4. 在源文件里替换语言 <a class="header-anchor" href="#_4-在源文件里替换语言" aria-label="Permalink to &quot;4. 在源文件里替换语言&quot;">​</a></h2><p>复制中文PSD为英文版，保留真实商品与尺寸线，逐个替换文字层。再复制日文版，选支持日文字形的字体，检查缺字、符号和换行。标题变长时先用短标题版本，再调整文本框宽度，最后考虑拆图。</p><p>练习里尺寸说明可单独放在商品下方。L/W/H指引必须对应同一顺序，英文与日文数值完全一致。特殊警示、使用限制和发货例外不能放成几乎看不见的小字。</p><h2 id="_5-对照检查三件事" tabindex="-1">5. 对照检查三件事 <a class="header-anchor" href="#_5-对照检查三件事" aria-label="Permalink to &quot;5. 对照检查三件事&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查</th><th>怎样实际做</th></tr></thead><tbody><tr><td>数字</td><td>把三语言文案并排，逐个核220/150/120与1/1/1</td></tr><tr><td>表达</td><td>看是否新增“防水”“食品级”或无依据比较</td></tr><tr><td>版面</td><td>各版缩到手机宽度，看标题、单位和例外说明</td></tr></tbody></table><p>单位错就回换算记录，文本错就改文字层，背景错就改背景。准确文字不通过整图重新生成来修。最终交付词表、审定文本、PSD状态与语言版本文件；当前没有当地语言审校或平台实际导入。英文完整模板<a href="./../prompts/P16">P16</a>，日文<a href="./../prompts/P17">P17</a>，尺寸<a href="./../prompts/P18">P18</a>。</p>`,18)])])}const b=a(o,[["render",i]]);export{m as __pageData,b as default};
